const svservbase = @import("sv-serv-base.zig"); const CF = svservbase.CF; const Ctxz = svservbase.Ctxz; const GUAR_LIST = svservbase.GUAR_LIST; const Slot = svservbase.Slot; const bannPrin = svservbase.bannPrin; const guarChec = svservbase.guarChec; const jsonBool = svservbase.jsonBool; const jsonInte = svservbase.jsonInte; const jsonStrz = svservbase.jsonStrz; const listEmpt = svservbase.listEmpt; const listWoulEmpt = svservbase.listWoulEmpt; const optiStrzWrit = svservbase.optiStrzWrit; const outpWoulEmpt = svservbase.outpWoulEmpt; const plusWrit = svservbase.plusWrit; const shelJson = svservbase.shelJson; const strzLess = svservbase.strzLess;
pub fn routTaskList(ctxz: *Ctxz, allo: std.mem.Allocator, iozz: std.Io, strm: *std.Io.net.Stream.Writer, requ: http.Requ) !void { const snap = ctxz.sche.snap(iozz); const nowz_loca = taskTime.localNow(); var body: std.Io.Writer.Allocating = .init(allo); const wrtr = &body.writer; try wrtr.print("{{\"ok\":true,\"ready\":{},\"fileOk\":{},\"reloads\":{d},\"fires\":{d}," ++ "\"total\":{d},\"armed\":{d},\"off\":{d},\"armErrorCount\":{d},\"tasks\":[", .{ snap.read, snap.rawz_okay, snap.relo_coun, snap.fire_coun, snap.tota, snap.arme, snap.offz, snap.arme_erro }); { try ctxz.sche.mute.lock(iozz); defer ctxz.sche.mute.unlock(iozz); if (ctxz.sche.load) |load| { for (load.task, 0..) |task, inde| { if (inde > 0) try wrtr.writeAll(","); try wrtr.writeAll("{\"id\":"); try std.json.Stringify.encodeJsonString(task.id, .{}, wrtr); try wrtr.writeAll(",\"type\":"); try std.json.Stringify.encodeJsonString(task.type, .{}, wrtr); try wrtr.print(",\"on\":{},\"kind\":", .{task.on}); try std.json.Stringify.encodeJsonString(task.kind, .{}, wrtr); try wrtr.writeAll(",\"run\":"); try std.json.Stringify.encodeJsonString(task.run, .{}, wrtr); try optiStrzWrit(wrtr, "sche", task.sche); try optiStrzWrit(wrtr, "cwd", task.cwd); try optiStrzWrit(wrtr, "shell", task.shell); try optiStrzWrit(wrtr, "cmt", task._cmt); try optiStrzWrit(wrtr, "lock", task.lock); if (task.catc) |catc| try wrtr.print(",\"catc\":{d}", .{catc}); try wrtr.writeAll(",\"ids\":"); if (task.ids) |idsz| { try wrtr.writeAll("["); for (idsz, 0..) |item, posi| { if (posi > 0) try wrtr.writeAll(","); try std.json.Stringify.encodeJsonString(item, .{}, wrtr); } try wrtr.writeAll("]"); } else try wrtr.writeAll("null"); if (task.plus) |plus| try plusWrit(wrtr, plus, ",\"plus\":") else try wrtr.writeAll(",\"plus\":null"); try optiStrzWrit(wrtr, "plat", task.plat); try optiStrzWrit(wrtr, "acc", task.acc); if (task.dela) |valu| try wrtr.print(",\"dela\":{d}", .{valu}) else try wrtr.writeAll(",\"dela\":null"); if (task.noLog) |valu| try wrtr.print(",\"noLog\":{}", .{valu}) else try wrtr.writeAll(",\"noLog\":null"); if (task.tmo) |valu| try wrtr.print(",\"tmo\":{d}", .{valu}) else try wrtr.writeAll(",\"tmo\":null"); if (task.@"try") |valu| try wrtr.print(",\"try\":{d}", .{valu}) else try wrtr.writeAll(",\"try\":null"); try wrtr.print(",\"winOnly\":{}", .{taskStor.winzOnlyChec(task.type)}); if (ctxz.sche.fireCoun(task.id)) |fire| { try wrtr.print(",\"fires\":{d},\"lastFire\":{d},\"armedKind\":\"{s}\"", .{ fire.coun, fire.last_msec, fire.kind }); if (ctxz.sche.fireNext(task.id, nowz_loca)) |next| { try wrtr.print(",\"nextStamp\":{d}", .{next}); } else try wrtr.writeAll(",\"nextStamp\":null"); if (ctxz.sche.loopStat(task.id)) |loop| { try wrtr.print(",\"restarts\":{d},\"alive\":{}", .{ loop.rest, loop.aliv }); } else try wrtr.writeAll(",\"restarts\":null,\"alive\":null"); if (ctxz.sche.probStat(task.id)) |prob| { try wrtr.writeAll(",\"probeState\":"); try std.json.Stringify.encodeJsonString(prob, .{}, wrtr); } else try wrtr.writeAll(",\"probeState\":null"); } else { try wrtr.writeAll(",\"fires\":0,\"lastFire\":0,\"armedKind\":null,\"nextStamp\":null,\"restarts\":null,\"alive\":null,\"probeState\":null"); } if (ctxz.sche.runzLast(allo, iozz, task.id)) |last| { try wrtr.print(",\"lastCode\":{d},\"lastMs\":{d},\"lastWhen\":", .{ last.code, last.elap_msec }); try std.json.Stringify.encodeJsonString(last.when, .{}, wrtr); } else try wrtr.writeAll(",\"lastCode\":null,\"lastMs\":null,\"lastWhen\":null"); if (std.mem.eql(u8, task.type, "chai")) { if (ctxz.sche.chaiView(iozz, task.id)) |view| { const coun = if (task.ids) |idsz| idsz.len else 0; try wrtr.print(",\"chain\":{{\"state\":\"{s}\",\"idx\":{d},\"total\":{d},\"ran\":{d},\"failed\":{d},\"nextMin\":{d},\"start\":{d},\"next\":{d},\"paused\":{},\"step\":", .{ if (view.wait) "wait" else "run", view.indx, coun, view.ranz, view.fail, view.next_minu, view.star_msec, view.next_msec, view.paus }); const step: []const u8 = if (task.ids) |idsz| (if (view.indx < idsz.len) idsz[view.indx] else "") else ""; try std.json.Stringify.encodeJsonString(step, .{}, wrtr); try wrtr.writeAll("}"); } else try wrtr.writeAll(",\"chain\":null"); } try wrtr.writeAll("}"); } try wrtr.writeAll("],\"armErrors\":["); for (ctxz.sche.arme_erro, 0..) |erro, inde| { if (inde > 0) try wrtr.writeAll(","); try wrtr.writeAll("{\"id\":"); try std.json.Stringify.encodeJsonString(erro.iden, .{}, wrtr); try wrtr.writeAll(",\"why\":"); try std.json.Stringify.encodeJsonString(erro.whyz, .{}, wrtr); try wrtr.writeAll("}"); } try wrtr.writeAll("],\"rejects\":["); for (load.reje, 0..) |reje, inde| { if (inde > 0) try wrtr.writeAll(","); try wrtr.print("{{\"index\":{d},\"id\":", .{reje.inde}); try std.json.Stringify.encodeJsonString(reje.iden, .{}, wrtr); try wrtr.writeAll(",\"why\":"); try std.json.Stringify.encodeJsonString(reje.whyz, .{}, wrtr); try wrtr.writeAll("}"); } try wrtr.writeAll("]"); } else { try wrtr.writeAll("],\"armErrors\":[],\"rejects\":[]"); } } try wrtr.writeAll(",\"root\":"); try std.json.Stringify.encodeJsonString(ctxz.sche.root, .{}, wrtr); try wrtr.writeAll(",\"queue\":"); try ctxz.sche.queuWrit(iozz, wrtr); var etag_buff: [24]u8 = undefined; const etag = http.etagHash(&etag_buff, wrtr.buffered()); try wrtr.print(",\"ticks\":{d},\"uptime\":{d}}}", .{ snap.tick_coun, snap.upti_msec }); try http.respEtagSend(strm, requ.ifzz_none_matc, etag, wrtr.buffered()); }
pub fn routTaskSave(ctxz: *Ctxz, allo: std.mem.Allocator, iozz: std.Io, strm: *std.Io.net.Stream.Writer, body_opti: ?[]u8) !void { const body = body_opti orelse return http.respSend(strm, 400, "Bad Request", "{\"error\":\"bad_body\"}"); const task_list = std.json.parseFromSliceLeaky([]taskStor.Task, allo, body, .{ .allocate = .alloc_always, .ignore_unknown_fields = true }) catch return http.respSend(strm, 400, "Bad Request", "{\"error\":\"bad_json\",\"hint\":\"expected an array of task objects\"}"); if (task_list.len > CF.task_maxz) return http.respSend(strm, 400, "Bad Request", "{\"error\":\"too_many_tasks\"}"); for (task_list) |*task| task.* = taskStor.norm(task.*); for (task_list, 0..) |task, inde| { if (taskStor.vali(task)) |whyz| { var resp: std.Io.Writer.Allocating = .init(allo); try resp.writer.print("{{\"error\":\"invalid_task\",\"index\":{d},\"id\":", .{inde}); try std.json.Stringify.encodeJsonString(task.id, .{}, &resp.writer); try resp.writer.writeAll(",\"why\":"); try std.json.Stringify.encodeJsonString(whyz, .{}, &resp.writer); try resp.writer.writeAll("}"); return http.respSend(strm, 400, "Bad Request", resp.writer.buffered()); } } for (task_list, 0..) |task, inde| { for (task_list[inde + 1 ..]) |othe| { if (!std.mem.eql(u8, task.id, othe.id)) continue; var resp: std.Io.Writer.Allocating = .init(allo); try resp.writer.writeAll("{\"error\":\"duplicate_id\",\"id\":"); try std.json.Stringify.encodeJsonString(task.id, .{}, &resp.writer); try resp.writer.writeAll("}"); return http.respSend(strm, 400, "Bad Request", resp.writer.buffered()); } } var outz: std.Io.Writer.Allocating = .init(allo); try taskListWrit(allo, ctxz.sche.root, &outz.writer, task_list); taskStor.save(allo, iozz, ctxz.sche.root, outz.writer.buffered()) catch return http.respSend(strm, 500, "Internal Server Error", "{\"error\":\"save_failed\"}"); ctxz.sche.relo(iozz) catch {}; ctxz.sche.loopReco(iozz); var resp: std.Io.Writer.Allocating = .init(allo); try resp.writer.print("{{\"ok\":true,\"count\":{d}}}", .{task_list.len}); try http.respSend(strm, 200, "OK", resp.writer.buffered()); }
pub fn routTaskTogg(ctxz: *Ctxz, allo: std.mem.Allocator, iozz: std.Io, strm: *std.Io.net.Stream.Writer, body_opti: ?[]u8) !void { const body = body_opti orelse return http.respSend(strm, 400, "Bad Request", "{\"error\":\"bad_body\"}"); const pars = std.json.parseFromSliceLeaky(std.json.Value, allo, body, .{ .allocate = .alloc_always }) catch return http.respSend(strm, 400, "Bad Request", "{\"error\":\"bad_json\"}"); const iden = jsonStrz(pars, "id") orelse ""; if (taskStor.idenVali(iden) != null) return http.respSend(strm, 400, "Bad Request", "{\"error\":\"bad_id\"}"); const want: ?bool = jsonBool(pars, "on"); var load = taskStor.load(allo, iozz, ctxz.sche.root) catch return http.respSend(strm, 500, "Internal Server Error", "{\"error\":\"load_failed\"}"); defer load.dein(); if (!load.rawz_okay) return http.respSend(strm, 409, "Conflict", "{\"error\":\"task_file_unreadable\",\"hint\":\"fix the JSON by hand first\"}"); var foun = false; var nowz_onzz = false; for (load.task) |*task| { if (!std.mem.eql(u8, task.id, iden)) continue; task.on = want orelse !task.on; nowz_onzz = task.on; foun = true; break; } if (!foun) return http.respSend(strm, 404, "Not Found", "{\"error\":\"no_such_task\"}"); var outz: std.Io.Writer.Allocating = .init(allo); try taskListWrit(allo, ctxz.sche.root, &outz.writer, load.task); taskStor.save(allo, iozz, ctxz.sche.root, outz.writer.buffered()) catch return http.respSend(strm, 500, "Internal Server Error", "{\"error\":\"save_failed\"}"); ctxz.sche.relo(iozz) catch {}; ctxz.sche.loopReco(iozz); var resp: std.Io.Writer.Allocating = .init(allo); try resp.writer.print("{{\"ok\":true,\"on\":{}}}", .{nowz_onzz}); try http.respSend(strm, 200, "OK", resp.writer.buffered()); }
pub fn routTaskLogz(ctxz: *Ctxz, allo: std.mem.Allocator, iozz: std.Io, strm: *std.Io.net.Stream.Writer, quer: []const u8) !void { const iden = http.querValu(quer, "id") orelse ""; if (taskStor.idenVali(iden)) |_| return http.respSend(strm, 400, "Bad Request", "{\"error\":\"bad_id\"}"); const data = ctxz.sche.logzRead(allo, iozz, iden, CF.logz_tail_maxz) catch |erro| { if (erro == error.NoLogYet) return http.respRawzSend(strm, 200, "OK", "text/plain; charset=utf-8", ""); return http.respSend(strm, 500, "Internal Server Error", "{\"error\":\"log_read_failed\"}"); }; try http.respRawzSend(strm, 200, "OK", "text/plain; charset=utf-8", data); }
pub fn taskListWrit(allo: std.mem.Allocator, root: []const u8, wrtr: *std.Io.Writer, task_list: []const taskStor.Task) !void { try wrtr.writeAll("[\n\n"); for (task_list, 0..) |task, inde| { if (inde > 0) try wrtr.writeAll(",\n\n"); try wrtr.writeAll("{\"type\":"); try std.json.Stringify.encodeJsonString(task.type, .{}, wrtr); if (task.sche) |sche| { try wrtr.writeAll(",\"sche\":"); try std.json.Stringify.encodeJsonString(sche, .{}, wrtr); } if (task.dela) |dela| try wrtr.print(",\"dela\":{d}", .{dela}); if (task.plus) |plus| try plusWrit(wrtr, plus, ",\"plus\":"); try wrtr.writeAll(",\"id\":"); try std.json.Stringify.encodeJsonString(task.id, .{}, wrtr); try wrtr.print(",\"on\":{}", .{task.on}); if (task.@"try") |valu| try wrtr.print(",\"try\":{d}", .{valu}); if (task.tmo) |valu| try wrtr.print(",\"tmo\":{d}", .{valu}); try wrtr.writeAll(",\"kind\":"); try std.json.Stringify.encodeJsonString(task.kind, .{}, wrtr); if (task.noLog) |nolo| try wrtr.print(",\"noLog\":{}", .{nolo}); if (task.plat) |plat| { try wrtr.writeAll(",\"plat\":"); try std.json.Stringify.encodeJsonString(plat, .{}, wrtr); } if (task.acc) |acco| { try wrtr.writeAll(",\"acc\":"); try std.json.Stringify.encodeJsonString(acco, .{}, wrtr); } if (task.cwd) |cwdz| { try wrtr.writeAll(",\"cwd\":"); try std.json.Stringify.encodeJsonString(cwdz, .{}, wrtr); } if (task.shell) |shel| { try wrtr.writeAll(",\"shell\":"); try std.json.Stringify.encodeJsonString(shel, .{}, wrtr); } if (task.lock) |lock| { try wrtr.writeAll(",\"lock\":"); try std.json.Stringify.encodeJsonString(lock, .{}, wrtr); } if (task.catc) |catc| try wrtr.print(",\"catc\":{d}", .{catc}); if (task.ids) |idsz| { try wrtr.writeAll(",\"ids\":["); for (idsz, 0..) |item, posi| { if (posi > 0) try wrtr.writeAll(","); try std.json.Stringify.encodeJsonString(item, .{}, wrtr); } try wrtr.writeAll("]"); } if (task._cmt) |cmtz| { try wrtr.writeAll(",\"_cmt\":"); try std.json.Stringify.encodeJsonString(cmtz, .{}, wrtr); } const auto = taskStor.autoRunz(allo, root, task.id) catch null; defer if (auto) |autz| allo.free(autz); const auto_same = if (auto) |autz| std.mem.eql(u8, autz, task.run) else false; if (!auto_same and task.run.len > 0) { try wrtr.writeAll(",\"run\":"); try std.json.Stringify.encodeJsonString(task.run, .{}, wrtr); } try wrtr.writeAll("}"); } try wrtr.writeAll("\n\n]\n"); }
